'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { ipcMain, app, shell } = require('electron');
const { CHANNELS } = require('./ipc-channels');
const { createDomainMutexes, MUTEX_DOMAINS } = require('./mutex');

// Generated by `npm run licenses` and committed. Read through the main process
// rather than imported by the renderer: it's ~190KB of license text that has no
// business in the module graph, and the renderer's CSP sets connect-src 'none',
// so it could not fetch() the file anyway.
const LICENSES_PATH = path.join(__dirname, '..', 'assets', 'licenses.json');

function notImplemented(domain, method) {
  return async () => ({
    ok: false,
    error: { code: 'NOT_IMPLEMENTED', message: `${domain}.${method} is not implemented yet` },
  });
}

/**
 * NCOW-31: the few methods of a mutexed domain that deliberately opt OUT of
 * that domain's lock. Everything else stays locked, which is what this file did
 * for every method of all four mutexed domains before now.
 *
 * Expressed as an opt-out (not an opt-in list of locked methods) on purpose: a
 * method added to a mutexed domain later is then serialized by default, and
 * only becomes unlocked if someone deliberately names it here. The inverse
 * would silently ship new mutating handlers with no lock at all.
 *
 * Why the proxy domain needs any exemption: its lock is now also taken by
 * engine-context.js's launch-time stale-config regeneration, whose restart can
 * legitimately hold it for up to pm2Control.startOrRestart()'s 60s health-check
 * window. The renderer's boot sequence awaits proxy.getStatus() before it
 * renders anything at all (renderer/app.js) and the status pill/poller keeps
 * asking, so locking that would turn exactly the upgrade launch this
 * regeneration exists for into a blank window for up to a minute. getStatus and
 * getRecentLogs are also the only two proxy methods that are pure reads —
 * getStatus lists pm2 apps, getRecentLogs tails two log files off disk. Neither
 * touches the pm2-supervised process or any main-process state, so running one
 * mid-restart cannot corrupt anything; the worst case is a status snapshot that
 * is already stale by the time it is rendered, which is true of every poll tick
 * regardless. testConnection and start/stopLogTail stay locked: the first was
 * locked before this change and would otherwise start failing spuriously
 * against a proxy that is mid-restart, and the log-tail pair mutate
 * engine-context.js's single `logTailUnsubscribe` slot, where two interleaved
 * callers leak a subscription.
 */
const UNSERIALIZED_METHODS = {
  proxy: ['getStatus', 'getRecentLogs'],
  // NCOW-32: update:check reaches neither pm2Control nor the config
  // directory (see autoUpdate.js's performCheck — it only ever talks to
  // GitHub's Releases API on macOS, or electron-updater's own metadata
  // fetch on Windows/Linux) and is fired automatically at every app startup,
  // racing exactly the launch-time background restart that can hold the
  // proxy lock for up to 60s. update:install is the one method of this
  // domain that actually reaches into shared proxy state
  // (installUpdateAndRestart -> stopProxyForShutdown) and stays locked (see
  // DOMAIN_MUTEX_ALIASES below); queuing this pure status read behind a
  // restart would delay every update-status broadcast for no corresponding
  // safety benefit, mirroring proxy's own getStatus/getRecentLogs exemption.
  update: ['check'],
  // NCOW-47: apiKey.getMasked only calls secretStore.load() and masks the
  // result for display (engine-context.js) — it persists nothing and cannot
  // race validateAndSave/clear in any way that corrupts state; the worst
  // case is a masked value that is already stale by the time it renders,
  // same as proxy's getStatus/getRecentLogs and update's check above.
  // clear is NOT listed here — it deletes the encrypted key and stays locked
  // via DOMAIN_MUTEX_ALIASES below, for its whole (fast, synchronous) body.
  //
  // NCOW-50: validateAndSave IS listed here now too, despite persisting the
  // key on success — for a different reason than the pure reads above.
  // Wave-8's integration review of NCOW-47 measured that this method awaits
  // nvidiaKey.validateApiKey() (up to two sequential 10s network round trips
  // against NVIDIA, engine-context.js) BEFORE it ever touches secretStore —
  // and NCOW-47 had this whole handler, including that network wait, locked
  // behind this alias. Composed with NCOW-45's uninstall alias (which
  // reserves claudeCode+config+proxy synchronously and holds all three until
  // it settles — the right call for multi-lock fairness), a slow/offline
  // NVIDIA endpoint turned one Validate-Key click into a ~20s hold on ALL
  // THREE of those locks the moment a user issued an Uninstall afterward —
  // freezing window AND tray Start/Stop/Restart, proxy:testConnection, every
  // claudeCode:* method, and Uninstall's own confirm, with no feedback. See
  // this task's own description for the full reproduction and measured
  // timings.
  //
  // The fix is not "stop locking validateAndSave" — NCOW-47's guarantee (a
  // write here must never interleave with config.generate's
  // secretStore.load()) still has to hold. It is "stop locking it HERE":
  // validateAndSave now acquires mutexes.config itself, directly, inside
  // engine-context.js — but only around the actual secretStore.save() call,
  // after validateApiKey() has already settled. That is a synchronous,
  // microseconds-long critical section, matching the standard every other
  // entry in this table already applies; the network wait ahead of it now
  // holds no lock at all. See engine-context.js's apiKey.validateAndSave for
  // the actual critical section, and configGen.regenerateStaleConfig's
  // injected runProxyOperation (engine-context.js) for the established
  // precedent of an engine-side critical section acquired against this same
  // shared `mutexes` object rather than through this file's automatic
  // per-method wrapping.
  //
  // This is why validateAndSave is opted out HERE rather than removed from
  // DOMAIN_MUTEX_ALIASES's `apiKey: 'config'` entry below: that alias is
  // still exactly right for `clear`, which has no network component and is
  // correctly locked for its whole (trivial) body.
  apiKey: ['getMasked', 'validateAndSave'],
  // NCOW-50 AC#5: config.getManifest is an equally pure read of the same
  // manifest.json config.generate writes — manifestStore.readManifest()
  // (engine-context.js's getManifest()) is a bare fs.readFileSync +
  // JSON.parse, no different in kind from apiKey.getMasked's
  // secretStore.load()+mask above, or proxy's getStatus/getRecentLogs.
  // NCOW-47 exempted apiKey.getMasked on exactly this standard but left
  // config.getManifest locked — an inconsistency with no live impact before
  // now (config's own critical sections were already short; see
  // mutex.js's exactly-one-caller argument for why nothing ever raced it in
  // practice) but one that would have quietly gotten worse the moment ANY
  // sufficiently long config-lock holder existed — which validateAndSave's
  // pre-fix network wait briefly was. Applying the same exemption standard
  // here removes the inconsistency outright. `generate` remains the one
  // config method with a genuine mutating concern, and stays locked.
  config: ['getManifest'],
};

/**
 * NCOW-32: aliases two IPC domains onto the `proxy` mutex because their
 * handlers reach into the same shared state the `proxy` domain already
 * guards. This is the domain's *only* mutating concern for `update`:
 * `update.install()` (installUpdateAndRestart -> stopProxyForShutdown,
 * src/main/autoUpdate.js) stops the very same pm2-supervised proxy the
 * launch-time background restart and a user-clicked Start/Stop/Restart
 * already serialize against each other through mutexes.proxy.
 *
 * For `uninstall`, a single alias is not enough: `uninstall.run()`
 * (src/engine/uninstall.js) mutates THREE shared-state domains in one call —
 * it removes Claude Code's settings file (removeClaudeCodeSettings(), the
 * `claudeCode` domain), calls pm2Control.remove() (the `proxy` domain, the
 * only one NCOW-32 originally covered), and, on purge, deletes the config
 * directory (fs.rmSync(opts.configDir), the `config` domain). NCOW-45 widened
 * this entry to an array of all three so an Uninstall click is serialized
 * against every mutex it actually touches, not just proxy's — without this,
 * a purge-uninstall could still interleave with an in-flight
 * claudeCode:configure/claudeCode:remove or config:generate the same way it
 * could interleave with a background restart before NCOW-32.
 *
 * Without this alias, an Uninstall click (or an update install) could
 * interleave with an in-flight restart: pm2Control.remove()'s
 * deleteAppIfPresent()+save() racing the restart's own
 * deleteAppIfPresent()->pm2.start() can leave a running proxy behind after
 * "uninstall complete", or a config directory Uninstall is deleting out from
 * under a restart that is concurrently regenerating it, or Uninstall's
 * settings-file removal racing an in-flight claudeCode:configure/remove.
 *
 * Deliberately NOT added to MUTEX_DOMAINS in mutex.js — neither `uninstall`
 * nor `update` needs a *lock of its own*; each only needs to share locks
 * that already exist for domains with an independent mutating concern, so
 * aliasing keeps createDomainMutexes() (and its own "exactly these domains"
 * test in mutex.test.js) describing only those domains.
 *
 * Distinct from main/index.js's before-quit shutdown path, which stays
 * deliberately unserialized against these locks (a wedged pm2 must never
 * make the app unquittable, per CLAUDE.md) — that path calls
 * stopProxyForShutdown() directly, outside any IPC handler, so it is
 * unaffected by this alias table.
 *
 * NCOW-47: `apiKey` aliases onto `config` for the same reason as the two
 * above — it has a real mutating concern (validateAndSave/clear persist and
 * delete the encrypted NVIDIA key via secretStore.save()/clear(),
 * engine-context.js) that shares state with an operation the `config`
 * domain already guards: config.generate reads that same key via
 * secretStore.load() *inside* the config lock (engine-context.js's
 * config.generate). Without this alias, an in-flight `apikey:clear` IPC call
 * racing a `config:generate` could interleave a delete with a read that
 * bakes the key into litellm.env, or the reverse ordering could hand
 * generate a NO_KEY failure mid-write against a key a save() had already
 * queued behind it — either way, nothing serialized the two. (There is
 * currently no shipped UI caller for the `apiKey.clear` channel at all — see
 * src/renderer/app.js and src/renderer/views/setup-view.js, the only two
 * `window.nimProxy.apiKey.*` call sites in the app (`getMasked` and
 * `validateAndSave` — never `clear`) — so today this alias is defence-in-
 * depth against a reachable IPC race, not a click a user can actually
 * trigger; `validateAndSave` DOES
 * have a real UI caller, the Setup wizard's "Validate & Save" button, so the
 * alias is load-bearing for that half regardless.) apiKey has no
 * mutating concern of its own beyond this one, so — like uninstall/update —
 * it gets no dedicated entry in MUTEX_DOMAINS (mutex.js), only this alias.
 * apiKey.getMasked is a pure read and stays exempt via UNSERIALIZED_METHODS
 * above rather than through this table.
 *
 * NCOW-50: this alias is still exactly right for `clear` — a synchronous,
 * no-network body that is correctly locked in full via this table — but
 * `validateAndSave` no longer resolves its lock through here at all: it is
 * now also listed in UNSERIALIZED_METHODS above, and instead acquires
 * `mutexes.config` itself, directly, inside engine-context.js, wrapped
 * around only the secretStore.save() call rather than the network
 * validation ahead of it. See UNSERIALIZED_METHODS's own `apiKey` entry
 * above for the full reasoning (the ~20s uninstall-freeze this was found
 * to cause) and engine-context.js's apiKey.validateAndSave for the actual
 * critical section. This alias's `apiKey: 'config'` entry below is kept
 * (not narrowed to just `clear`) precisely because `clear` still needs it —
 * removing the entry would silently unlock `clear` too.
 *
 * diagnostics.run is not the only other reader of that identical secretStore
 * key — nor is it aliased here, and neither are the other two. All three
 * read the key into a local and never persist or delete it, so nothing
 * corrupts if one of them races apiKey's validateAndSave/clear; the worst
 * case in every case below is a stale-key read, same as diagnostics.run's
 * own NOT_CONFIGURED-on-a-since-cleared-key case:
 *
 *   - diagnostics.run (engine-context.js) — deliberately NOT aliased; see
 *     the comment on diagnostics.run itself for the fuller reasoning, which
 *     as of this fix pass also names catalog.fetch and proxy.testConnection
 *     below rather than reading as a census of one.
 *   - catalog.fetch (engine-context.js) — resolves to zero locks, exactly
 *     like diagnostics.run.
 *   - proxy.testConnection (engine-context.js) — locked, but under `proxy`,
 *     not `config`; different chains means it is NOT serialized against
 *     apiKey's writes either, it just isn't unserialized for this reason —
 *     it was already locked before NCOW-47 for reasons unrelated to the key
 *     (see UNSERIALIZED_METHODS' `proxy` entry above).
 *
 * prereqs.installLitellm was also checked (NCOW-47) and needs no alias: it
 * installs via uv/pipx/pip entirely outside the config directory
 * (prereqs.js), so it has no shared state with `config` (or any other
 * domain here) to race in the first place.
 */
const DOMAIN_MUTEX_ALIASES = {
  uninstall: ['claudeCode', 'config', 'proxy'],
  update: 'proxy',
  apiKey: 'config',
};

/**
 * NCOW-45: the one and only order in which ANY handler in this file may
 * acquire more than one domain lock at once — alphabetical by domain name,
 * chosen with no significance beyond being fixed and easy to re-derive
 * without consulting this file (so a future change can't accidentally
 * "reorder for readability" and silently invert it). `uninstall` is
 * currently the only multi-lock acquirer (see DOMAIN_MUTEX_ALIASES above);
 * confirmed by grep across src/ and test/ during NCOW-45 that no other
 * caller anywhere in this codebase ever holds more than one of these locks
 * at once, so adopting this order cannot contradict an order something else
 * already relies on.
 *
 * Why a single fixed order is deadlock-safe: a lock-ordering deadlock needs
 * a *cycle* — caller A holding lock X while waiting on lock Y, and caller B
 * holding Y while waiting on X. That requires at least two callers that each
 * acquire more than one lock, in opposite relative orders. With only one
 * multi-lock caller in the whole codebase, no such second caller exists to
 * form the other half of a cycle, so no cycle is possible regardless of
 * which order is picked. This constant exists anyway — instead of leaving
 * `uninstall` to just acquire its three in whatever order its array
 * happens to list them — so that IF a second multi-lock handler is ever
 * added, it inherits a pre-existing convention (sort its domains by this
 * same array, e.g. via resolveDomainLocks() below) rather than inventing an
 * independent order that could conflict with this one and reintroduce the
 * exact risk this comment just ruled out.
 */
const LOCK_ACQUISITION_ORDER = ['claudeCode', 'claudeDesktop', 'config', 'proxy'];

/**
 * NCOW-46: throws if `order` is not exactly a permutation of `domains`, or if
 * any domain referenced anywhere in `aliases` is missing from `order`.
 *
 * Why this matters: resolveDomainLocks() below sorts by
 * `order.indexOf(domain)`, and Array.prototype.indexOf returns -1 for a
 * domain that isn't listed. With exactly one domain missing, ordering still
 * happens to stay consistent (nothing else compares equal to it). With TWO OR
 * MORE domains missing, they all compare equal (-1 === -1), and
 * Array.prototype.sort's stability then means their relative order silently
 * collapses to whatever DOMAIN_MUTEX_ALIASES happened to list them in —
 * exactly the acquisition-order inconsistency LOCK_ACQUISITION_ORDER exists
 * to prevent, reintroduced without so much as a warning.
 *
 * Called once below, at module load, against the real
 * LOCK_ACQUISITION_ORDER/MUTEX_DOMAINS/DOMAIN_MUTEX_ALIASES: the check is a
 * handful of Set operations over four-element arrays (negligible, and paid
 * exactly once per process, not per IPC call), and a drift between these
 * three hand-maintained lists is exactly as broken on a user's machine as it
 * is in CI — a loud require()-time crash here is preferable to a build that
 * silently ships with the acquisition-order guarantee already gone. Exported
 * so a dedicated test can also exercise it directly against
 * deliberately-broken inputs (see ipc-mutex.test.js) without mutating this
 * module's real constants.
 */
function assertLockOrderIsConsistent(order, domains, aliases) {
  const orderSet = new Set(order);
  const domainSet = new Set(domains);
  const missingFromOrder = domains.filter((d) => !orderSet.has(d));
  const unknownInOrder = order.filter((d) => !domainSet.has(d));
  if (order.length !== domains.length || missingFromOrder.length > 0 || unknownInOrder.length > 0) {
    throw new Error(
      `LOCK_ACQUISITION_ORDER ${JSON.stringify(order)} must be exactly a permutation of MUTEX_DOMAINS ` +
        `${JSON.stringify(domains)} (missing: ${JSON.stringify(missingFromOrder)}, unexpected: ${JSON.stringify(unknownInOrder)})`
    );
  }
  const aliasedDomains = Object.values(aliases).flatMap((v) => (Array.isArray(v) ? v : [v]));
  const unlistedAliasDomains = [...new Set(aliasedDomains.filter((d) => !orderSet.has(d)))];
  if (unlistedAliasDomains.length > 0) {
    throw new Error(
      `DOMAIN_MUTEX_ALIASES references domain(s) ${JSON.stringify(unlistedAliasDomains)} missing from ` +
        `LOCK_ACQUISITION_ORDER ${JSON.stringify(order)}`
    );
  }
}

assertLockOrderIsConsistent(LOCK_ACQUISITION_ORDER, MUTEX_DOMAINS, DOMAIN_MUTEX_ALIASES);

/** Resolves the ordered list of locks a domain's methods must hold before
 *  running: its own single lock if MUTEX_DOMAINS covers it, else its
 *  alias(es) from DOMAIN_MUTEX_ALIASES (normalized to an array whether the
 *  table lists one domain or several, sorted into LOCK_ACQUISITION_ORDER
 *  regardless of the order the table happens to list them in — so a future
 *  edit to that table can't silently invert the acquisition order — and
 *  deduplicated by resolved lock identity), else an empty array.
 *
 *  NCOW-46: the dedupe step matters even though no current
 *  DOMAIN_MUTEX_ALIASES entry resolves two of its aliased domains to the same
 *  underlying mutex function (MUTEX_DOMAINS/createDomainMutexes() hands out
 *  one distinct mutex per domain) — it IS reachable via the `opts.mutexes`
 *  injection point registerIpcHandlers() itself accepts, e.g. a hand-built
 *  mutexes object or a test fixture that reuses one mutex for two domain
 *  keys. Without deduping, withLocks() below would reserve that one
 *  underlying FIFO chain twice for the same call, and the second reservation
 *  can never get its turn — its own release depends on the shared run it is
 *  blocking, a permanent deadlock. Deduping degrades that case to holding the
 *  shared mutex once instead. */
function resolveDomainLocks(mutexes, domain) {
  if (mutexes[domain]) return [mutexes[domain]];
  const alias = DOMAIN_MUTEX_ALIASES[domain];
  if (!alias) return [];
  const aliasDomains = Array.isArray(alias) ? alias : [alias];
  const sorted = [...aliasDomains].sort(
    (a, b) => LOCK_ACQUISITION_ORDER.indexOf(a) - LOCK_ACQUISITION_ORDER.indexOf(b)
  );
  const seen = new Set();
  const locks = [];
  for (const d of sorted) {
    const lock = mutexes[d];
    if (!lock || seen.has(lock)) continue;
    seen.add(lock);
    locks.push(lock);
  }
  return locks;
}

/**
 * Composes N single-domain lock decorators into one that holds ALL of them
 * for the full duration of `fn`, reserving a queue slot on each — in
 * `locks`' order — SYNCHRONOUSLY, in the same tick, before returning.
 *
 * That synchronous, in-order reservation is what keeps a multi-lock caller's
 * position in any one shared chain consistent with a single-lock competitor
 * for that same domain: if this is invoked before a single-lock call that
 * only wants (say) the last domain in `locks`, this reserves its slot on
 * that domain's chain in the very same synchronous pass that reserves its
 * slots on every other domain — so the competitor, invoked afterwards,
 * necessarily queues behind it there too. An earlier version of this
 * function nested lock acquisition instead (only enqueuing on locks[1] once
 * locks[0]'s turn had actually arrived, and so on) — which reproduces
 * LOCK_ACQUISITION_ORDER's intended acquisition order in isolation, but lets
 * a single-lock competitor for the LAST domain in `locks` win a queue race
 * against a multi-lock caller that was invoked first, because the
 * single-lock call reaches that domain's chain in one synchronous step while
 * the multi-lock call is still working through the microtasks of its earlier
 * locks. Reserving every slot up front closes that race. (Caught by this
 * task's own regression test for AC#3 — see ipc-mutex.test.js.)
 *
 * Each reservation's callback resolves a per-lock "ready" signal and then
 * returns the SAME shared `fn(...args)` promise — so, per
 * createDomainMutex()'s own chain-of-promises design (mutex.js), every one
 * of these locks stays occupied, blocking whatever else is queued behind it,
 * until `fn` has fully settled, not merely until its own turn arrived. `fn`
 * itself only starts once every lock's ready signal has resolved, i.e. once
 * every lock's turn has arrived.
 *
 * The exactly-one-lock case is special-cased to plain `lock(fn)` rather than
 * running it through the barrier machinery below: the barrier adds a couple
 * of extra microtask hops before `fn` actually starts (resolving a "ready"
 * signal and awaiting a Promise.all of it are each their own tick), and one
 * regression-tested caller (tray-actions.test.js's mutex-identity check)
 * depends on ipc.js's own single-lock timing matching tray.js's direct
 * `mutexes.proxy.run(fn)` call tick-for-tick. Every domain but `uninstall`
 * still resolves to exactly one lock, so this keeps their behaviour, and
 * that test, byte-for-byte unchanged.
 */
function withLocks(locks, fn) {
  if (locks.length <= 1) return locks.length === 1 ? locks[0](fn) : fn;
  return (...args) => {
    const readySignals = locks.map(() => {
      let resolve;
      const promise = new Promise((res) => {
        resolve = res;
      });
      return { promise, resolve };
    });

    const sharedRun = Promise.all(readySignals.map((s) => s.promise)).then(() => fn(...args));

    for (let i = 0; i < locks.length; i++) {
      const { resolve } = readySignals[i];
      locks[i](() => {
        resolve();
        return sharedRun;
      })();
    }

    return sharedRun;
  };
}

const ALLOWED_EXTERNAL_URL_PREFIXES = [
  'https://build.nvidia.com',
  'https://claude.com/docs',
  // Broad enough to cover this project's own repo plus every dependency
  // homepage listed in the Licenses view, which are overwhelmingly GitHub.
  'https://github.com/',
  'https://gitlab.com/',
  'https://www.npmjs.com/',
];

// Handlers that don't need an engine module — always available, regardless
// of which engine domains have landed yet. Callers may still override these
// via the `handlers.app` argument if a future need arises.
const builtinAppHandlers = {
  getVersion: async () => ({ ok: true, data: app.getVersion() }),
  getPlatform: async () => ({ ok: true, data: process.platform }),
  openExternal: async ({ url } = {}) => {
    if (typeof url !== 'string' || !ALLOWED_EXTERNAL_URL_PREFIXES.some((p) => url.startsWith(p))) {
      return { ok: false, error: { code: 'URL_NOT_ALLOWED', message: 'URL is not in the allowlist' } };
    }
    await shell.openExternal(url);
    return { ok: true };
  },
  getLicenses: async () => {
    try {
      return { ok: true, data: JSON.parse(fs.readFileSync(LICENSES_PATH, 'utf8')) };
    } catch (err) {
      // A missing or corrupt file means someone shipped without running
      // `npm run licenses`. Say so plainly rather than showing an empty list
      // that reads as "this app bundles nothing".
      return {
        ok: false,
        error: { code: 'LICENSES_UNAVAILABLE', message: `Could not read licenses.json: ${err.message}` },
      };
    }
  },
};

/**
 * @param {Record<string, Record<string, Function>>} handlers
 *   Per-domain handler implementations, e.g. { proxy: { start: async () => ... } }.
 *   Any channel without a supplied handler falls back to a NOT_IMPLEMENTED stub,
 *   so this module is safe to call before every engine module has landed.
 * @param {{mutexes?: ReturnType<typeof createDomainMutexes>}} [opts]
 *   NCOW-31: the per-domain locks to serialize mutating handlers against.
 *   MUST be the same object engine-context.js used for its own background
 *   proxy work (index.js passes `context.mutexes` straight through) — a
 *   separate set here would silently mean the launch-time config regeneration
 *   and a user-initiated Start/Stop are locked against different chains, i.e.
 *   not serialized at all. Defaults to a private set only so this function
 *   stays callable in isolation. NCOW-32/NCOW-45/NCOW-47: 'uninstall',
 *   'update', and 'apiKey' have no entry of their own in this set (see
 *   mutex.js's MUTEX_DOMAINS) — they resolve onto one or more of
 *   `mutexes.{proxy,config,claudeCode}` via DOMAIN_MUTEX_ALIASES above
 *   instead. `uninstall` resolves to all three (acquired in
 *   LOCK_ACQUISITION_ORDER via withLocks(), see both above); `update` still
 *   resolves to `proxy` alone; `apiKey` resolves to `config` alone
 *   (validateAndSave/clear only — getMasked opts out via
 *   UNSERIALIZED_METHODS above).
 */
function registerIpcHandlers(handlers = {}, opts = {}) {
  const mergedHandlers = { ...handlers, app: { ...builtinAppHandlers, ...handlers.app } };
  const mutexes = opts.mutexes ?? createDomainMutexes();

  for (const [domain, spec] of Object.entries(CHANNELS)) {
    const domainHandlers = mergedHandlers[domain] || {};
    const locks = resolveDomainLocks(mutexes, domain);
    const unserialized = UNSERIALIZED_METHODS[domain] ?? [];
    for (const [method, channel] of Object.entries(spec.invoke || {})) {
      const impl = domainHandlers[method] || notImplemented(domain, method);
      const shouldLock = locks.length > 0 && !unserialized.includes(method);
      const wrapped = shouldLock ? withLocks(locks, impl) : impl;
      ipcMain.handle(channel, async (_event, ...args) => {
        try {
          return await wrapped(...args);
        } catch (err) {
          return { ok: false, error: { code: err.code || 'UNEXPECTED', message: err.message } };
        }
      });
    }
  }
}

module.exports = {
  registerIpcHandlers,
  // NCOW-46: exported so ipc-mutex.test.js can reference these directly
  // instead of only ever exercising them behaviorally through uninstall.
  resolveDomainLocks,
  withLocks,
  assertLockOrderIsConsistent,
  DOMAIN_MUTEX_ALIASES,
  LOCK_ACQUISITION_ORDER,
};
